        console.log(`    target: ${n.target.join(" ")}`);
        console.log(`    summary: ${n.failureSummary.replace(/\n/g, " | ")}`);
      });
    }
    console.log(`incomplete: ${r.incomplete.length}`);
    for (const v of r.incomplete) {
      console.log(`- [${v.impact}] ${v.id}: ${v.help}`);
    }
  };

  summarize("Collapsed", collapsed);
  summarize("Expanded", expanded);

  await browser.close();
  const total = collapsed.violations.length + expanded.violations.length;
  process.exit(total > 0 ? 1 : 0);
})();
